 taskTypeNames:{SALES:['销售计划','Sales Plans'],RECEIPT:['入库备货单','Receipt & Preparation'],LOT:['备货作业','Preparation Work'],LOAD:['装车与出库','Loading & Outbound'],COUNT:['库存盘点','Stocktaking'],LOADING_PLAN:['装车计划','Loading Plans'],VEHICLE:['车辆到厂','Vehicle Arrival'],ARRIVAL:['到厂后建单','Plan After Arrival'],GATE:['车辆出厂','Gate Exit']},
 kind(k){return ({CO_RECEIPT_EDIT:['入库备货单修改','Revise Receipt'],CO_RECEIPT_SITE:['入库现场审核','Site Receipt Review'],CO_RECEIPT_PRODUCTION:['入库生产审核','Production Receipt Review'],CO_WORK:['备货作业','Preparation Work'],CO_COMPLETION_REVIEW:['完工复核','Completion Review'],CO_AMEND_REVIEW:['备货更正复核','Preparation Amendment Review'],CO_MATCH:['配货匹配','Stock Matching'],CO_LOAD_START:['开始装车','Start Loading'],CO_LOAD_CONFIRM:['装车实物确认','Confirm Physical Loading'],CO_LOAD_REVIEW:['现场装车审核','Site Loading Review'],CO_DEPART:['车辆离场','Vehicle Departure'],CO_OUTBOUND_SUBMIT:['提交正式出库','Submit Formal Outbound'],CO_LOGISTICS_REVIEW:['物流出库审核','Logistics Outbound Review'],CO_FORMAL_OUTBOUND:['生产终审出库','Final Outbound Approval'],CO_VEHICLE_REVIEW:['车辆变更复核','Vehicle Change Review'],CO_EXCEPTION:['装车异常复核','Loading Exception Review'],CO_ARRIVAL:['车辆到厂登记','Vehicle Arrival'],CO_ARRIVAL_PLAN:['到厂后建单','Plan After Arrival'],CO_COUNT:['库存实盘','Physical Stocktaking'],CO_COUNT_REVIEW:['盘点独立复核','Independent Count Review']})[k]||Copper461.kind.call(this,k);},
