 owns(p=location.pathname){return p==='/customers'||/^\/customers\/master-data\/customers\/(?:new|[0-9a-f-]{36})$/.test(p)||/^\/customers\/contracts\/(?:new|[0-9a-f-]{36}(?:\/edit)?)$/.test(p)||p==='/overview/warning-settings'||p==='/overview'&&['todos','alerts'].includes(new URLSearchParams(location.search).get('management'));},
