  const rules=this.card('库存与业务预警','Inventory & Business Alerts','<div class="c461-fields">'+this.label('项目 *','Project *','<select id="c461-warning-project">'+this.options(d.items.map(s=>({id:s.project_id,name:s.project_name})),item.project_id)+'</select>')+this.label('适用范围','Scope','<output>'+this.L('当前项目授权仓库与客户','Authorized warehouses and customers')+'</output>')+field('呆库预警天数 *','Stock Age Alert Days *','co_stock_age_days',3650,1)+field('待审批提醒小时 *','Approval Reminder Hours *','co_approval_hours',87600,1)+field('计划到期提醒天数 *','Plan Expiry Reminder Days *','co_plan_expiry_days',3650)+'</div>'+toggle('显示总览预警','Show Overview Alerts','co_show_overview_alerts','在信息总览集中查看库存与业务预警','Show stock and business alerts on the overview')+toggle('待办提示','Task Reminders','co_show_todo_reminders','按当前账号的办理权限提示，关闭不影响待办查询','Reminders follow action permissions; task access remains available.')+'<p class="c461-muted-text">'+this.L('呆库从实际入库时间计算；待办从当前节点实际发生时间计算；计划到期按发运月份月末计算。','Stock age starts at receipt. Reminders use the current stage time. Plans expire at the end of their shipment month.')+'</p>');
  this.page('预警设置','Warning Settings','CO-04','<div class="c461-settings-grid">'+nav+'<form id="c461-warning-form" class="c461-main"><div id="c461-warning-rules">'+rules+'</div><div id="c461-warning-config" hidden>'+this.card('当前配置','Current Configuration',this.facts([['项目','Project',item.project_name],['版本','Version',item.version],['呆库预警天数','Stock Age Days',item.co_stock_age_days],['待审批提醒小时','Approval Hours',item.co_approval_hours],['计划到期提醒天数','Plan Expiry Days',item.co_plan_expiry_days],['最近更新','Updated',this.time(item.updated_at)],['更新人员','Updated By',item.updated_by_name||'—']]))+'</div><p class="error" id="c461-warning-error" role="alert"></p><footer class="c461-form-footer"><p>'+this.L('当前版本','Current Version')+' <span data-no-i18n>r'+item.version+'</span></p><div><button type="button" class="button secondary" id="c461-warning-cancel">'+this.L('取消修改','Cancel Changes')+'</button><button class="button primary" '+(!item.editable?'disabled':'')+'>✓ '+this.L('保存设置','Save Settings')+'</button></div></footer><section class="c461-card" id="c461-warning-history"><h2>'+this.L('最近修改','Recent Changes')+'</h2>'+history+'</section></form></div>');
